import subprocess

# Test m3: DeprecationWarning when key returns None
test_code = """
import warnings
from cachetools import cachedmethod

class MyClass:
    def __init__(self):
        self.cache = {}

    @cachedmethod(lambda self: self.cache)
    def method(self, x):
        return x

obj = MyClass()

# Test normal case - no warning
with warnings.catch_warnings(record=True) as w:
    warnings.simplefilter("always")
    result = obj.method(5)
    none_warnings = [x for x in w if issubclass(x.category, DeprecationWarning)]
    print(f"Normal call: result={result}, deprecation_warnings={len(none_warnings)}")

# Test None key case - should warn
def bad_key(self, x):
    return None

class MyClass2:
    def __init__(self):
        self.cache = {}

    @cachedmethod(lambda self: self.cache, key=bad_key)
    def method(self, x):
        return x

obj2 = MyClass2()
with warnings.catch_warnings(record=True) as w:
    warnings.simplefilter("always")
    result = obj2.method(5)
    none_warnings = [x for x in w if issubclass(x.category, DeprecationWarning)]
    print(f"None key call: result={result}, deprecation_warnings={len(none_warnings)}")
    if none_warnings:
        print(f"Warning message: {none_warnings[0].message}")
"""

with open('/tmp/test_m3.py', 'w') as f:
    f.write(test_code)

result = subprocess.run(['python', '/tmp/test_m3.py'], capture_output=True, text=True)
print(result.stdout)
if result.stderr:
    print("Stderr:", result.stderr[:500])
